{'name': 'generate_code', 'arguments': {'code': 'from typing import Optional\nfrom sqlmodel import Field, SQLModel\nfrom datetime import datetime\n\nclass AnalyticsBase(SQLModel):\n    """\n    Base model for analytics data. This model defines the common fields\n    that are shared across different analytics-related models.\n    """\n    event_name: str = Field(..., description="Name of the analytics event")\n    event_timestamp: datetime = Field(default_factory=datetime.utcnow, description="Timestamp of the event")\n    user_id: Optional[int] = Field(default=None, description="ID of the user associated with the event")\n    metadata: Optional[dict] = Field(default=None, description="Additional metadata for the event")\n\nclass AnalyticsCreate(AnalyticsBase):\n    """\n    Model for creating new analytics entries. Inherits from AnalyticsBase.\n    """\n    pass\n\nclass AnalyticsRead(AnalyticsBase):\n    """\n    Model for reading analytics entries. Inherits from AnalyticsBase.\n    """\n    id: int = Field(..., description="Primary key of the analytics entry")\n\nclass AnalyticsUpdate(SQLModel):\n    """\n    Model for updating existing analytics entries. All fields are optional.\n    """\n    event_name: Optional[str] = Field(default=None, description="Updated name of the analytics event")\n    event_timestamp: Optional[datetime] = Field(default=None, description="Updated timestamp of the event")\n    user_id: Optional[int] = Field(default=None, description="Updated ID of the user associated with the event")\n    metadata: Optional[dict] = Field(default=None, description="Updated metadata for the event")', 'language': 'python', 'imports': ['from typing import Optional', 'from sqlmodel import Field, SQLModel', 'from datetime import datetime'], 'exports': ['AnalyticsBase', 'AnalyticsCreate', 'AnalyticsRead', 'AnalyticsUpdate'], 'dependencies': ['sqlmodel'], 'documentation': "This module defines the data models for analytics-related operations in the application. It includes base models, as well as models for creating, reading, and updating analytics data. The models are designed to integrate seamlessly with SQLModel and follow FastAPI's data validation patterns.", 'quality_score': 10}}